mapper.update:
UPDATE notification
SET read_at = CURRENT_TIMESTAMP
WHERE recipient_id = #{recipientId}
  AND id = #{id}
  AND read_at IS NULL

UPDATE notification
SET read_at = NULL
WHERE recipient_id = #{recipientId}
  AND id = #{id}
  AND read_at IS NOT NULL

UPDATE notification
SET dismissed_at = CURRENT_TIMESTAMP
WHERE recipient_id = #{recipientId}
  AND id = #{id}
  AND dismissed_at IS NULL
  AND resolved_at IS NULL

UPDATE notification
SET dismissed_at = NULL, resolved_at = NULL, read_at = NULL
WHERE recipient_id = #{recipientId}
  AND id = #{id}
  AND (dismissed_at IS NOT NULL OR resolved_at IS NOT NULL)

UPDATE notification
SET resolved_at = #{resolvedAt}
WHERE workspace_id = #{workspaceId}
  AND recipient_id = #{recipientId}
  AND id = #{id}
  AND type IN ()
  AND resolved_at IS NULL

